import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int m = r.nextInt(), n = r.nextInt();
        long[] a = new long[m], c = new long[n];
        long total = 0;
        for (int i = 0; i < m; i++) { a[i] = r.nextLong(); total += a[i]; }
        for (int i = 0; i < n; i++) c[i] = r.nextLong();
        Arrays.sort(a);  // ascending; a[m-1-i] is the i-th largest
        Arrays.sort(c);
        long cursor = 0, saving = 0, best = 0;
        for (int j = 0; j < n; j++) {
            long threshold = c[j];
            if (cursor + threshold + 2 > m) break;
            if (j == n - 1) {  // the last center must also take every leftover item
                best = Math.max(best, saving + a[1] + a[0]);
                break;
            }
            cursor += threshold;
            saving += a[(int) (m - 1 - cursor)] + a[(int) (m - 2 - cursor)];
            cursor += 2;
            best = Math.max(best, saving);
        }
        System.out.println(total - best);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

