func main() {
	m, n := readInt(), readInt()
	a := make([]int, m)
	c := make([]int, n)
	total := 0
	for i := range a {
		a[i] = readInt()
		total += a[i]
	}
	for i := range c {
		c[i] = readInt()
	}
	slices.Sort(a)
	slices.Reverse(a)
	slices.Sort(c)
	cursor, saving, best := 0, 0, 0
	for j, threshold := range c {
		if cursor+threshold+2 > m {
			break
		}
		if j == n-1 { // the last center must also take every leftover item
			best = max(best, saving+a[m-2]+a[m-1])
			break
		}
		cursor += threshold
		saving += a[cursor] + a[cursor+1]
		cursor += 2
		best = max(best, saving)
	}
	fmt.Println(total - best)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
